using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using PaymentBatchProcessingService.Domain.Entities;
using PaymentBatchProcessingService.Domain.Helpers;

namespace PaymentBatchProcessingService.Infrastructure.DB.Configurations;

public sealed class PaymentBatchConfiguration : IEntityTypeConfiguration<PaymentBatch>
{
    public void Configure(EntityTypeBuilder<PaymentBatch> builder)
    {
        //SQL table name
        builder.ToTable("PaymentBatches");

        //Primary key configuration, GUID is generated by the application, not the database
        builder.HasKey(x => x.Id);
        builder.Property(x => x.Id).ValueGeneratedNever();

        //LegalEntityId is required
        builder.Property(x => x.LegalEntityId).IsRequired();

        //SourceBankAccountId is required
        builder.Property(x => x.SourceBankAccountId).IsRequired();

        //Currency is required, has a maximum length of 3, and is stored as non-Unicode in the database
        builder.Property(x => x.Currency).HasConversion<string>().HasMaxLength(Constants.MaxCurrencyLength).IsUnicode(false).IsRequired();

        //Status is required, has a maximum length of 20, and is stored as non-Unicode in the database
        builder.Property(x => x.Status).HasConversion<string>().HasMaxLength(Constants.MaxStatusLength).IsUnicode(false).IsRequired();

        //CreatedAtUtc is required, stored as datetime2 in the database, and is always treated as UTC
        builder.Property(x => x.CreatedAtUtc).HasColumnType("datetime2")
            .HasConversion(
                value => value,
                value => DateTime.SpecifyKind(value, DateTimeKind.Utc)).IsRequired();

        //To which LegalEntity and BankAccount this PaymentBatch belongs, with foreign key constraints and delete behavior set to Restrict
        builder.HasOne<LegalEntity>().WithMany().HasForeignKey(x => x.LegalEntityId).OnDelete(DeleteBehavior.Restrict);

        builder.HasOne<BankAccount>().WithMany().HasForeignKey(x => x.SourceBankAccountId).OnDelete(DeleteBehavior.Restrict);
    }
}
